// =============================================================
// SAOC — app/(marketing)/media-kit/UsageSection.tsx
// Server Component — clear space, minimum size and the Do / Don't pairs. The wording is the
// presentation's own (SA Orchid Council Logo Presentation.pdf, "Use and misuse"), reproduced
// verbatim; the four illustrations are generated by scripts/generate-saoc-media-kit.py.
// =============================================================

import Image from 'next/image';

interface UsageIllustration {
  file: string;
  width: number;
  height: number;
}

export interface UsageSectionProps {
  illustrations: UsageIllustration[];
}

const CLEAR_SPACE =
  'Clear space on all four sides equals one quarter of the emblem width. Nothing sets inside it.';
const MINIMUM_SIZE =
  'Minimum emblem height is 24px on screen, 8mm in print. Below that the throat detail closes up and the mark should be set larger rather than simplified.';

interface UsagePair {
  kind: 'DO' | "DON'T";
  file: string;
  copy: string;
}

const PAIRS: UsagePair[] = [
  {
    kind: 'DO',
    file: 'usage-do-horizontal.png',
    copy: 'Set the lockup as a single object at the specified proportions, on parchment, bone or sage.',
  },
  {
    kind: "DON'T",
    file: 'usage-dont-horizontal.png',
    copy: 'Do not re-space the gap, letter-space the wordmark, or shrink the emblem against the type.',
  },
  {
    kind: 'DO',
    file: 'usage-do-vertical.png',
    copy: "Keep the vertical lockup's emblem flush to the wordmark width.",
  },
  {
    kind: "DON'T",
    file: 'usage-dont-vertical.png',
    copy: 'Do not float a small emblem above the name. It breaks the lockup.',
  },
];

export function UsageSection({ illustrations }: UsageSectionProps) {
  const sizeOf = (file: string): UsageIllustration => {
    const found = illustrations.find((entry) => entry.file === file);
    if (!found) throw new Error(`media kit manifest has no usage illustration ${file}`);
    return found;
  };

  return (
    <>
      <div className="max-w-[720px] space-y-4 font-sans text-[16px] leading-[1.55] text-ink/80">
        <p>{CLEAR_SPACE}</p>
        <p>{MINIMUM_SIZE}</p>
      </div>
      <div className="mt-8 grid grid-cols-1 gap-6 md:grid-cols-2">
        {PAIRS.map((pair) => {
          const image = sizeOf(pair.file);
          return (
            <figure key={pair.file} className="flex flex-col border border-rule bg-parchment p-4">
              <p className="mb-3 font-mono text-[11px] uppercase tracking-[0.22em] text-ink">
                {pair.kind}
              </p>
              <Image
                src={`/images/media-kit/${pair.file}`}
                alt={`${pair.kind} example`}
                width={image.width}
                height={image.height}
                unoptimized
                loading="lazy"
                className="h-auto w-full"
              />
              <figcaption className="mt-3 font-sans text-[13px] leading-[1.55] text-ink/70">
                {pair.copy}
              </figcaption>
            </figure>
          );
        })}
      </div>
    </>
  );
}
